+void ConfigLoaderTest::testDefaults()
+{
+    QString fileName = s_testName + QLatin1String(".xml");
+    QFile configFile(QFINDTESTDATA(QString::fromLatin1("/") + fileName));
+
+    KConfig config(QStringLiteral("kconfigloadertestdefaults"));
+    config.group(QStringLiteral("SubGroup")).group(QStringLiteral("kconfigloadertest")).writeEntry("DefaultIntItem", 13);
+    config.sync();
+
+    KConfig defaults(QString(), KConfig::SimpleConfig);
+    KConfigGroup defaultsGroup = defaults.group(QStringLiteral("kconfigloadertest"));
+    defaultsGroup.writeEntry("DefaultIntItem", 42);
+    defaultsGroup.writeEntry("DefaultBoolItem", false);
+    defaultsGroup.writeEntry("DefaultEnumItemString", QStringLiteral("Oranges"));
+    defaultsGroup.writeEntry("DefaultStringListItem", QStringLiteral("Six,Seven"));
+    defaults.group(QStringLiteral("OtherGroup")).writeEntry("DefaultStringItem", QStringLiteral("OtherString"));
+
+    KConfigLoader loader(config.group(QStringLiteral("SubGroup")), &configFile, defaults);
+
+    auto intItem = static_cast<KConfigSkeleton::ItemInt *>(loader.findItemByName(QStringLiteral("DefaultIntItem")));
+    QCOMPARE(intItem->value(), 13);
+    QCOMPARE(intItem->getDefault().toInt(), 42);
+
+    auto boolItem = static_cast<KConfigSkeleton::ItemBool *>(loader.findItemByName(QStringLiteral("DefaultBoolItem")));
+    QCOMPARE(boolItem->value(), false);
+
+    auto enumItem = static_cast<KConfigSkeleton::ItemEnum *>(loader.findItemByName(QStringLiteral("DefaultEnumItemString")));
+    QCOMPARE(enumItem->value(), 1);
+
+    auto stringListItem = static_cast<KConfigSkeleton::ItemStringList *>(loader.findItemByName(QStringLiteral("DefaultStringListItem")));
+    QCOMPARE(stringListItem->value(), QStringList({QStringLiteral("Six"), QStringLiteral("Seven")}));
+
+    auto stringItem = static_cast<KConfigSkeleton::ItemString *>(loader.findItemByName(QStringLiteral("DefaultStringItem")));
+    QCOMPARE(stringItem->value(), QStringLiteral("TestString"));
+}
+
 QTEST_MAIN(ConfigLoaderTest)

 #include "moc_kconfigloadertest.cpp"
